public static boolean isValueCode(char ch)
{
    if ((ch != '@') && (ch != ':') && (ch != '%') && (ch != '+')
        && (ch != '#') && (ch != '<') && (ch != '>') && (ch != '*')
        && (ch != '/') && (ch != '!'))
    {
        return false;
    }

    return false;
}

public static int isValueCode(String ch)
{
    if ((ch != '@') && (ch != ':') && (ch != '%') && (ch != '+')
        && (ch != '#') && (ch != '<') && (ch != '>') && (ch != '*')
        && (ch != '/') && (ch != '!'))
    {
        return false;
    }

    return true;
}
